import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const ROOT = process.cwd();
const VERSION = "v5-r7-neural-player-discovery";
const MARKER = "MVP_TRAINER_V5_R7_NEURAL_PLAYER_DISCOVERY";
const BACKUP_SUFFIX = ".pre-v5-r7-neural-player-discovery.bak";

const EXPECTED = {
  "intelligence": "0e209e07a30ebe0d160e4af10285a286dcd101e32ca614697a2afa4e8076df47",
  "panel": "f6b19c739c2d6eaa40969b9c63c042cb5faf5f7ac1497c8a310e440e888c44fb",
  "page": "0adcb1d38ae6a3e6015ba52dbe1e38f4f0d84220159aad521f4c5d5c2997bb2a",
  "mini": "d01910d8f08be89ba676ff95e9d515988b0638e13ac9f8f4dd69610acf62e4d7"
};
const REPLACEMENTS = {
  "intelligence": "",
  "panel": "",
  "page": "",
  "mini": ""
};

function normalize(text) {
  return text.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
}

function sha256(text) {
  return crypto.createHash("sha256").update(normalize(text), "utf8").digest("hex");
}

function stop(message) {
  console.error("");
  console.error(`MVP Trainer V5 R7 stopped: ${message}`);
  console.error("No source files were written.");
  process.exit(1);
}

function findMiniPlayer() {
  const direct = path.join(ROOT, "src", "features", "music", "MusicMiniPlayer.tsx");
  if (fs.existsSync(direct)) return direct;

  const folder = path.join(ROOT, "src", "features", "music");
  if (!fs.existsSync(folder)) return null;

  for (const name of fs.readdirSync(folder)) {
    if (!name.endsWith(".tsx")) continue;
    const full = path.join(folder, name);
    try {
      const source = fs.readFileSync(full, "utf8");
      if (source.includes("export function MusicMiniPlayer")) return full;
    } catch {
      // Keep scanning.
    }
  }
  return null;
}

const FILES = {
  intelligence: path.join(ROOT, "src", "lib", "musicIntelligence.ts"),
  panel: path.join(ROOT, "src", "features", "music", "MusicIntelligencePanel.tsx"),
  page: path.join(ROOT, "src", "features", "music", "MusicPage.tsx"),
  mini: findMiniPlayer(),
};

if (!FILES.mini) stop("MusicMiniPlayer source file was not found.");

for (const [key, file] of Object.entries(FILES)) {
  if (!file || !fs.existsSync(file)) stop(`${key} source file was not found. Run this from the repo root.`);
}

const originals = Object.fromEntries(
  Object.entries(FILES).map(([key, file]) => [key, fs.readFileSync(file, "utf8")]),
);

const alreadyInstalled = Object.values(originals).every((source) => source.includes(MARKER));
if (alreadyInstalled) {
  console.log("MVP Trainer V5 R7 Neural Player + Discovery is already installed.");
  process.exit(0);
}

for (const [key, source] of Object.entries(originals)) {
  if (source.includes(MARKER)) {
    stop(`${key} already contains part of R7 while the other files do not. Restore the repo or send the changed files before retrying.`);
  }
  const actual = sha256(source);
  if (actual !== EXPECTED[key]) {
    stop(`${key} does not match the exact current source used to build R7. Expected ${EXPECTED[key].slice(0, 12)}…, found ${actual.slice(0, 12)}….`);
  }
}

// Everything validates before the first write.
for (const [key, file] of Object.entries(FILES)) {
  fs.writeFileSync(file + BACKUP_SUFFIX, originals[key], "utf8");
}

for (const [key, file] of Object.entries(FILES)) {
  const source = Buffer.from(REPLACEMENTS[key], "base64").toString("utf8");
  fs.writeFileSync(file, source, "utf8");
}

const validation = {
  intelligence:
    fs.readFileSync(FILES.intelligence, "utf8").includes('"darker"') &&
    fs.readFileSync(FILES.intelligence, "utf8").includes('"surprise"') &&
    fs.readFileSync(FILES.intelligence, "utf8").includes("buildDiscoveryRadar"),
  panel:
    !fs.readFileSync(FILES.panel, "utf8").includes("mvp-v5-modes") &&
    !fs.readFileSync(FILES.panel, "utf8").includes("DISCOVERY RADAR"),
  page:
    fs.readFileSync(FILES.page, "utf8").includes("tr10-radarPanel") &&
    fs.readFileSync(FILES.page, "utf8").includes("buildDiscoveryRadar"),
  mini:
    fs.readFileSync(FILES.mini, "utf8").includes("tr-neuralSteering") &&
    fs.readFileSync(FILES.mini, "utf8").includes("SURPRISE ME") &&
    fs.readFileSync(FILES.mini, "utf8").includes("startMvpNeuralRadio"),
};

if (!Object.values(validation).every(Boolean)) {
  console.error("R7 post-write validation failed. Restoring backups now.");
  for (const [key, file] of Object.entries(FILES)) {
    fs.writeFileSync(file, originals[key], "utf8");
  }
  stop("post-write validation failed; originals were restored.");
}

console.log("");
console.log("MVP Trainer V5 R7 Neural Player + Discovery applied successfully.");
console.log(`(${VERSION})`);
console.log("");
console.log("Updated:");
console.log("- src/lib/musicIntelligence.ts");
console.log("- src/features/music/MusicIntelligencePanel.tsx");
console.log("- src/features/music/MusicPage.tsx");
console.log(`- ${path.relative(ROOT, FILES.mini)}`);
console.log("");
console.log("Next: npm run build");
